import java.util.Scanner;

public class CoopSaver {
    // Piggy savings account of an imagined school co-operative
    private String holder;
    private double balance;
    private static int accounts = 0;

    public CoopSaver(String h, double opening) {
        holder = h;
        if (opening >= 0)
            balance = opening;
        accounts++;
    }
    public void deposit(double amt) {
        if (amt > 0)
            balance = balance + amt;
    }
    public boolean withdraw(double amt) {
        if (amt <= 0 || amt > balance)
            return false;
        balance = balance - amt;
        return true;
    }
    public void show() {
        System.out.println(holder + " has Rs " + balance);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        CoopSaver a = new CoopSaver(sc.next(), sc.nextDouble());
        a.deposit(sc.nextDouble());
        boolean ok = a.withdraw(sc.nextDouble());
        if (!ok)
            System.out.println("Withdrawal refused");
        a.show();
        System.out.println("Accounts opened = " + accounts);
    }
}
