        RainGauge g = new RainGauge();
        int n = sc.nextInt();
        for (int i = 0; i < n; i++)
            g.add(sc.nextDouble());
        System.out.println("Days = " + g.days + ", total = " + g.total);
        System.out.println("Average = " + g.average());
        System.out.println("Gauges = " + gauges);
    }
}
